DAN_STATIC_STR(dan_lit_2035, "\n/* ---- dictionary {\320\276\320\277\320\270\321\201\320\260\320\275\320\270\320\265} ---- */\nstruct {D} {{ dan_hdr h; int64_t len, n, cap, slots; {K} *keys; {V} *vals; uint64_t *hashes; bool *alive; int64_t *index; }};\n\nstatic void {D}_destroy(dan_hdr *h) {{\n    {D} *d = ({D} *)(void *)h;\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {{ {RK}(d->keys[e]); {RV}(d->vals[e]); }}\n    dan_free(d->hashes);\n    dan_free(d);\n}}\nstatic {D} *{D}_new(void) {{\n    {D} *d = dan_alloc(sizeof *d);\n    dan_hdr_new(&d->h, {D}_destroy);\n    d->len = d->n = d->cap = d->slots = 0;\n    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;\n    return d;\n}}\nstatic {D} *{D}_new_detached(void) {{\n    {D} *d = dan_alloc(sizeof *d);\n    dan_hdr_detached(&d->h);\n    d->len = d->n = d->cap = d->slots = 0;\n    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;\n    return d;\n}}\nstatic {D} *{D}_share({D} *d) {{ if (d) dan_hdr_share(&d->h); return d; }}\nstatic void {D}_release({D} *d) {{ if (d) dan_hdr_release(&d->h, {D}_destroy); }}\nstatic void {D}_give({D} *d) {{ if (d) dan_hdr_give(&d->h, {D}_destroy); }}\n\n/* \320\262\321\201\320\265 \321\207\320\260\321\201\321\202\320\270 \321\201\320\273\320\276\320\262\320\260\321\200\321\217 - \320\262 \320\276\320\264\320\275\320\276\320\274 \320\261\320\273\320\276\320\272\320\265 \320\277\320\260\320\274\321\217\321\202\320\270 (\320\276\320\264\320\275\320\276 \320\262\321\213\320\264\320\265\320\273\320\265\320\275\320\270\320\265 \320\262\320\274\320\265\321\201\321\202\320\276 \320\277\321\217\321\202\320\270): \320\276\321\202\320\277\320\265\321\207\320\260\321\202\320\272\320\270,\n   \321\202\320\260\320\261\320\273\320\270\321\206\320\260 \320\277\320\276\320\270\321\201\320\272\320\260, \320\272\320\273\321\216\321\207\320\270, \320\267\320\275\320\260\321\207\320\265\320\275\320\270\321\217 \320\270 \320\277\321\200\320\270\320\267\320\275\320\260\320\272\320\270 \302\253\320\267\320\260\320\277\320\270\321\201\321\214 \320\265\321\201\321\202\321\214\302\273 \320\275\320\260 cap \320\267\320\260\320\277\320\270\321\201\320\265\320\271 */\nstatic void {D}_block({D} *d, int64_t cap) {{\n    int64_t s = 8;\n    while (s < 2 * cap) s *= 2;\n    size_t c = (size_t)cap, kb = (sizeof({K}) * c + 7) & ~(size_t)7, vb = (sizeof({V}) * c + 7) & ~(size_t)7;\n    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);\n    d->hashes = (uint64_t *)(void *)b;\n    d->index = (int64_t *)(void *)(b + 8 * c);\n    d->keys = ({K} *)(void *)(b + 8 * c + 8 * (size_t)s);\n    d->vals = ({V} *)(void *)(b + 8 * c + 8 * (size_t)s + kb);\n    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);\n    d->cap = cap;\n    d->slots = s;\n}}\nstatic void {D}_reindex({D} *d) {{\n    int64_t s = d->slots;\n    for (int64_t i = 0; i < s; i++) d->index[i] = -1;\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));\n        while (d->index[p] >= 0) p = (p + 1) & (s - 1);\n        d->index[p] = e;\n    }}\n}}\nstatic int64_t {D}_lookup(const {D} *d, {K} k, uint64_t h) {{\n    if (!d->slots) return -1;\n    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {{\n        int64_t e = d->index[p];\n        if (e < 0) return -1;\n        if (d->alive[e] && d->hashes[e] == h) {{ {K} a = d->keys[e], b = k; if ({EQ_K}) return e; }}\n    }}\n}}\nstatic void {D}_grow({D} *d) {{   /* \321\203\320\261\320\270\321\200\320\260\320\265\321\202 \321\203\320\264\320\260\320\273\321\221\320\275\320\275\321\213\320\265 \320\267\320\260\320\277\320\270\321\201\320\270 \320\270 \321\203\320\262\320\265\320\273\320\270\321\207\320\270\320\262\320\260\320\265\321\202 \321\202\320\260\320\261\320\273\320\270\321\206\321\203 */\n    int64_t cap = d->len * 2 < 8 \? 8 : d->len * 2, m = 0;\n    {K} *keys = d->keys; {V} *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;\n    int64_t n = d->n;\n    {D}_block(d, cap);\n    for (int64_t e = 0; e < n; e++) {{\n        if (!alive[e]) continue;\n        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;\n    }}\n    dan_free(hashes);\n    d->n = m;\n    {D}_reindex(d);\n}}\nstatic void {D}_put({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    int64_t e = {D}_lookup(d, k, h);\n    if (e >= 0) {{ {V} old = d->vals[e]; d->vals[e] = {SV}(v); {RV}(old); (void)old; return; }}\n    if (d->n == d->cap) {D}_grow(d);\n    e = d->n++;\n    d->keys[e] = {SK}(k); d->vals[e] = {SV}(v); d->hashes[e] = h; d->alive[e] = true; d->len++;\n    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n    d->index[p] = e;\n}}\n/* \320\267\320\260\320\277\320\270\321\201\321\214 \320\262 \320\275\320\276\320\262\321\213\320\271 \321\201\320\273\320\276\320\262\320\260\321\200\321\214 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\271, \320\272\320\276\321\202\320\276\321\200\321\213\320\265 \321\203\320\266\320\265 \321\203\321\207\321\202\320\265\320\275\321\213 (\320\272\320\276\320\277\320\270\321\217 \320\264\320\273\321\217 \320\267\320\260\320\264\320\260\321\207\320\270) */\nstatic void {D}_put_raw({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    if (d->n == d->cap) {D}_grow(d);\n    int64_t e = d->n++;\n    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;\n    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n");
DAN_STATIC_STR(dan_lit_2036, "    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n    d->index[p] = e;\n}}\n/* \320\274\320\265\321\201\321\202\320\276 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\321\217 \320\277\320\276 \320\272\320\273\321\216\321\207\321\203; \320\265\321\201\320\273\320\270 \320\272\320\273\321\216\321\207\320\260 \320\275\320\265\321\202, \320\267\320\260\320\277\320\270\321\201\321\214 \321\201\320\276\320\267\320\264\320\260\321\221\321\202\321\201\321\217 \321\201\320\276 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\265\320\274 v (\320\276\320\264\320\275\320\276 \320\276\320\261\321\200\320\260\321\211\320\265\320\275\320\270\320\265\n   \320\262\320\274\320\265\321\201\321\202\320\276 \320\277\320\276\320\273\321\203\321\207\320\270\321\202\321\214 \320\270 \320\267\320\260\320\277\320\270\321\201\320\260\321\202\321\214) */\nstatic {V} *{D}_slot({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    int64_t e = {D}_lookup(d, k, h);\n    if (e < 0) {{\n        if (d->n == d->cap) {D}_grow(d);\n        e = d->n++;\n        d->keys[e] = {SK}(k); d->vals[e] = {SV}(v); d->hashes[e] = h; d->alive[e] = true; d->len++;\n        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n        d->index[p] = e;\n    }}\n    return &d->vals[e];\n}}\nstatic {D} *{D}_from(int64_t n, const {K} *ks, const {V} *vs) {{\n    {D} *d = {D}_new();\n    for (int64_t i = 0; i < n; i++) {D}_put(d, ks[i], vs[i]);\n    return d;\n}}\nstatic {V} {D}_get(const {D} *d, {K} k, int line) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e < 0) dan_key_error({\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(k), line);\n    return d->vals[e];\n}}\nstatic {V} *{D}_at({D} *d, {K} k, int line) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e < 0) dan_key_error({\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(k), line);\n    return &d->vals[e];\n}}\nstatic bool {D}_contains(const {D} *d, {K} k) {{ return {D}_lookup(d, k, {HASH}) >= 0; }}\n{\320\235\320\220\320\231\320\242\320\230}static {V} {D}_get_or(const {D} *d, {K} k, {V} v) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    return e < 0 \? v : d->vals[e];\n}}\nstatic void {D}_remove({D} *d, {K} k) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e >= 0) {{ d->alive[e] = false; d->len--; {RK}(d->keys[e]); {RV}(d->vals[e]); }}\n}}\nstatic {LK} *{D}_keys(const {D} *d) {{\n    {LK} *r = {LK}_from(0, NULL);\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {LK}_push(r, d->keys[e]);\n    return r;\n}}\nstatic {LV} *{D}_values(const {D} *d) {{\n    {LV} *r = {LV}_from(0, NULL);\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {LV}_push(r, d->vals[e]);\n    return r;\n}}\n/* \320\272\320\276\320\277\320\270\321\217 \320\264\320\273\321\217 \320\270\320\267\320\274\320\265\320\275\320\265\320\275\320\270\321\217: \320\267\320\260\320\277\320\270\321\201\320\270 \320\277\320\265\321\200\320\265\320\275\320\276\321\201\321\217\321\202\321\201\321\217 \320\262\320\274\320\265\321\201\321\202\320\265 \321\201 \320\263\320\276\321\202\320\276\320\262\321\213\320\274\320\270 \320\276\321\202\320\277\320\265\321\207\320\260\321\202\320\272\320\260\320\274\320\270 (\320\261\320\265\320\267 \320\277\320\276\320\262\321\202\320\276\321\200\320\275\320\276\320\263\320\276\n   \320\262\321\213\321\207\320\270\321\201\320\273\320\265\320\275\320\270\321\217), \320\274\320\265\321\201\321\202\320\276 - \321\201 \320\267\320\260\320\277\320\260\321\201\320\276\320\274 \320\262\320\264\320\262\320\276\320\265, \321\207\321\202\320\276\320\261\321\213 \321\201\320\273\320\265\320\264\321\203\321\216\321\211\320\260\321\217 \320\267\320\260\320\277\320\270\321\201\321\214 \320\275\320\265 \320\277\320\265\321\200\320\265\321\201\321\202\321\200\320\260\320\270\320\262\320\260\320\273\320\260 \321\202\320\260\320\261\320\273\320\270\321\206\321\203 */\nstatic {D} *{D}_copy(const {D} *d) {{\n    {D} *r = {D}_new();\n    if (d->len == 0) return r;\n    int64_t cap = d->len * 2 < 8 \? 8 : d->len * 2, m = 0;\n    {D}_block(r, cap);\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        r->keys[m] = {SK}(d->keys[e]); r->vals[m] = {SV}(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;\n    }}\n    r->n = r->len = m;\n    {D}_reindex(r);\n    return r;\n}}\nstatic {D} *{D}_mut({D} **pp) {{\n    {D} *d = *pp;\n    if (d->h.rc > 1) {{ {D} *r = {D}_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }}\n    return d;\n}}\nstatic dan_str {D}_str(const {D} *d) {{\n    dan_buf b = {{ NULL, 0, 0 }};\n    dan_buf_add(&b, \"{{\");\n    bool first = true;\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        if (!first) dan_buf_add(&b, \", \");\n        first = false;\n        dan_buf_add(&b, {\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(d->keys[e]));\n        dan_buf_add(&b, \": \");\n        dan_buf_add(&b, {\320\241\320\242\320\240\320\236\320\232\320\220_\320\227}(d->vals[e]));\n    }}\n    dan_buf_add(&b, \"}}\");\n    return dan_buf_str(&b);\n}}\nstatic void {D}_write(const {D} *d) {{ fputs({D}_str(d), stdout); }}\n");
