/* ---- list [стр] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_Ls { dan_hdr h; int64_t len, cap; dan_str *items; };

static void dl_Ls_destroy(dan_hdr *h) {
    dl_Ls *l = (dl_Ls *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dan_str_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_Ls *dl_Ls_from(int64_t n, dan_str const *src) {
    dl_Ls *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_Ls_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dan_str));
    for (int64_t i = 0; i < n; i++) l->items[i] = dan_str_share(src[i]);
    return l;
}

static void dl_Ls_push(dl_Ls *l, dan_str v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dan_str));
    }
    l->items[l->len++] = dan_str_share(v);
}

static dan_str dl_Ls_get(const dl_Ls *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dan_str *dl_Ls_at(dl_Ls *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Ls_set(dl_Ls *l, int64_t i, dan_str v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_str old = l->items[i];
    l->items[i] = dan_str_share(v);
    dan_str_release(old);
    (void)old;
}

static void dl_Ls_write(const dl_Ls *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_quoted(l->items[i]);
    }
    putchar(']');
}

static void dl_Ls_insert(dl_Ls *l, int64_t i, dan_str v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Ls_push(l, v);
    dan_str last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dan_str));
    l->items[i] = last;
}

static void dl_Ls_remove(dl_Ls *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dan_str old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dan_str));
    l->len--;
    dan_str_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Ls *dl_Ls_copy(const dl_Ls *l) {
    return dl_Ls_from(l->len, l->items);
}

static inline dl_Ls *dl_Ls_share(dl_Ls *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Ls_release(dl_Ls *l) { if (l) dan_hdr_release(&l->h, dl_Ls_destroy); }
static inline void dl_Ls_give(dl_Ls *l) { if (l) dan_hdr_give(&l->h, dl_Ls_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Ls *dl_Ls_mut(dl_Ls **pp) {
    dl_Ls *l = *pp;
    if (l->h.rc > 1) {
        dl_Ls *r = dl_Ls_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Ls *dl_Ls_reversed(const dl_Ls *l) {
    dl_Ls *r = dl_Ls_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dan_str t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Ls *dl_Ls_slice(const dl_Ls *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Ls_from(b - a + 1, l->items + a);
}

static dan_str dl_Ls_str(const dl_Ls *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_quote_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Ls_find(const dl_Ls *l, dan_str b) {
    for (int64_t i = 0; i < l->len; i++) { dan_str a = l->items[i]; if (dan_str_eq(a, b)) return i; }
    return -1;
}
static bool dl_Ls_contains(const dl_Ls *l, dan_str b) { return dl_Ls_find(l, b) >= 0; }
static bool dl_Ls_eq(const dl_Ls *x, const dl_Ls *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dan_str a = x->items[i]; dan_str b = y->items[i]; if (!(dan_str_eq(a, b))) return false; }
    return true;
}


static dl_Ls *dan_str_chars(dan_str s) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (const char *p = s; *p;) {
        size_t k = dan_utf8_len_at(p);
        dl_Ls_push(r, dan_char_str(p, k));
        p += k;
    }
    return r;
}

static dl_Ls *dan_str_split(dan_str s, dan_str sep, int line) {
    if (!*sep) dan_error(DAN_MSG_EMPTY_SEARCH, line);
    dl_Ls *r = dl_Ls_from(0, NULL);
    size_t ls = strlen(sep);
    const char *p = s, *f;
    while ((f = strstr(p, sep)) != NULL) { dl_Ls_push(r, dan_str_sub(p, f)); p = f + ls; }
    dl_Ls_push(r, dan_strdup(p));
    return r;
}

/* words separated by any spaces, tabs and line breaks */
static dl_Ls *dan_str_split_ws(dan_str s) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    const char *p = s;
    for (;;) {
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (!*p) break;
        const char *a = p;
        while (*p && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') p++;
        dl_Ls_push(r, dan_str_sub(a, p));
    }
    return r;
}

static dan_str dl_Ls_join(const dl_Ls *l, dan_str sep) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, sep);
        dan_buf_add(&b, l->items[i]);
    }
    return dan_buf_str(&b);
}


/* ---- list [[стр]] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LLs { dan_hdr h; int64_t len, cap; dl_Ls* *items; };

static void dl_LLs_destroy(dan_hdr *h) {
    dl_LLs *l = (dl_LLs *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dl_Ls_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LLs *dl_LLs_from(int64_t n, dl_Ls* const *src) {
    dl_LLs *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LLs_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_Ls*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_Ls_share(src[i]);
    return l;
}

static void dl_LLs_push(dl_LLs *l, dl_Ls* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dl_Ls*));
    }
    l->items[l->len++] = dl_Ls_share(v);
}

static dl_Ls* dl_LLs_get(const dl_LLs *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dl_Ls* *dl_LLs_at(dl_LLs *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LLs_set(dl_LLs *l, int64_t i, dl_Ls* v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Ls* old = l->items[i];
    l->items[i] = dl_Ls_share(v);
    dl_Ls_release(old);
    (void)old;
}

static void dl_LLs_write(const dl_LLs *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dl_Ls_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LLs_insert(dl_LLs *l, int64_t i, dl_Ls* v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LLs_push(l, v);
    dl_Ls* last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dl_Ls*));
    l->items[i] = last;
}

static void dl_LLs_remove(dl_LLs *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Ls* old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dl_Ls*));
    l->len--;
    dl_Ls_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LLs *dl_LLs_copy(const dl_LLs *l) {
    return dl_LLs_from(l->len, l->items);
}

static inline dl_LLs *dl_LLs_share(dl_LLs *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LLs_release(dl_LLs *l) { if (l) dan_hdr_release(&l->h, dl_LLs_destroy); }
static inline void dl_LLs_give(dl_LLs *l) { if (l) dan_hdr_give(&l->h, dl_LLs_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LLs *dl_LLs_mut(dl_LLs **pp) {
    dl_LLs *l = *pp;
    if (l->h.rc > 1) {
        dl_LLs *r = dl_LLs_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LLs *dl_LLs_reversed(const dl_LLs *l) {
    dl_LLs *r = dl_LLs_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dl_Ls* t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LLs *dl_LLs_slice(const dl_LLs *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LLs_from(b - a + 1, l->items + a);
}

static dan_str dl_LLs_str(const dl_LLs *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dl_Ls_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LLs_find(const dl_LLs *l, dl_Ls* b) {
    for (int64_t i = 0; i < l->len; i++) { dl_Ls* a = l->items[i]; if (dl_Ls_eq(a, b)) return i; }
    return -1;
}
static bool dl_LLs_contains(const dl_LLs *l, dl_Ls* b) { return dl_LLs_find(l, b) >= 0; }
static bool dl_LLs_eq(const dl_LLs *x, const dl_LLs *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dl_Ls* a = x->items[i]; dl_Ls* b = y->items[i]; if (!(dl_Ls_eq(a, b))) return false; }
    return true;
}


/* ---- list [цел] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_Li { dan_hdr h; int64_t len, cap; int64_t *items; };

static void dl_Li_destroy(dan_hdr *h) {
    dl_Li *l = (dl_Li *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) DAN_NOREL(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_Li *dl_Li_from(int64_t n, int64_t const *src) {
    dl_Li *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_Li_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(int64_t));
    for (int64_t i = 0; i < n; i++) l->items[i] = DAN_ID(src[i]);
    return l;
}

static void dl_Li_push(dl_Li *l, int64_t v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(int64_t));
    }
    l->items[l->len++] = DAN_ID(v);
}

static int64_t dl_Li_get(const dl_Li *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static int64_t *dl_Li_at(dl_Li *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Li_set(dl_Li *l, int64_t i, int64_t v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    int64_t old = l->items[i];
    l->items[i] = DAN_ID(v);
    DAN_NOREL(old);
    (void)old;
}

static void dl_Li_write(const dl_Li *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_int(l->items[i]);
    }
    putchar(']');
}

static void dl_Li_insert(dl_Li *l, int64_t i, int64_t v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Li_push(l, v);
    int64_t last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(int64_t));
    l->items[i] = last;
}

static void dl_Li_remove(dl_Li *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    int64_t old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(int64_t));
    l->len--;
    DAN_NOREL(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Li *dl_Li_copy(const dl_Li *l) {
    return dl_Li_from(l->len, l->items);
}

static inline dl_Li *dl_Li_share(dl_Li *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Li_release(dl_Li *l) { if (l) dan_hdr_release(&l->h, dl_Li_destroy); }
static inline void dl_Li_give(dl_Li *l) { if (l) dan_hdr_give(&l->h, dl_Li_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Li *dl_Li_mut(dl_Li **pp) {
    dl_Li *l = *pp;
    if (l->h.rc > 1) {
        dl_Li *r = dl_Li_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Li *dl_Li_reversed(const dl_Li *l) {
    dl_Li *r = dl_Li_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { int64_t t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Li *dl_Li_slice(const dl_Li *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Li_from(b - a + 1, l->items + a);
}

static dan_str dl_Li_str(const dl_Li *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_int_to_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Li_find(const dl_Li *l, int64_t b) {
    for (int64_t i = 0; i < l->len; i++) { int64_t a = l->items[i]; if ((a == b)) return i; }
    return -1;
}
static bool dl_Li_contains(const dl_Li *l, int64_t b) { return dl_Li_find(l, b) >= 0; }
static bool dl_Li_eq(const dl_Li *x, const dl_Li *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { int64_t a = x->items[i]; int64_t b = y->items[i]; if (!((a == b))) return false; }
    return true;
}


