/* ---- list [[рац]] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LLr { dan_hdr h; int64_t len, cap; dl_Lr* *items; };

static void dl_LLr_destroy(dan_hdr *h) {
    dl_LLr *l = (dl_LLr *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dl_Lr_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LLr *dl_LLr_from(int64_t n, dl_Lr* const *src) {
    dl_LLr *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LLr_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_Lr*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_Lr_share(src[i]);
    return l;
}

static void dl_LLr_push(dl_LLr *l, dl_Lr* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dl_Lr*));
    }
    l->items[l->len++] = dl_Lr_share(v);
}

static dl_Lr* dl_LLr_get(const dl_LLr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dl_Lr* *dl_LLr_at(dl_LLr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LLr_set(dl_LLr *l, int64_t i, dl_Lr* v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Lr* old = l->items[i];
    l->items[i] = dl_Lr_share(v);
    dl_Lr_release(old);
    (void)old;
}

static void dl_LLr_write(const dl_LLr *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dl_Lr_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LLr_insert(dl_LLr *l, int64_t i, dl_Lr* v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LLr_push(l, v);
    dl_Lr* last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dl_Lr*));
    l->items[i] = last;
}

static void dl_LLr_remove(dl_LLr *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dl_Lr* old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dl_Lr*));
    l->len--;
    dl_Lr_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LLr *dl_LLr_copy(const dl_LLr *l) {
    return dl_LLr_from(l->len, l->items);
}

static inline dl_LLr *dl_LLr_share(dl_LLr *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LLr_release(dl_LLr *l) { if (l) dan_hdr_release(&l->h, dl_LLr_destroy); }
static inline void dl_LLr_give(dl_LLr *l) { if (l) dan_hdr_give(&l->h, dl_LLr_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LLr *dl_LLr_mut(dl_LLr **pp) {
    dl_LLr *l = *pp;
    if (l->h.rc > 1) {
        dl_LLr *r = dl_LLr_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LLr *dl_LLr_reversed(const dl_LLr *l) {
    dl_LLr *r = dl_LLr_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dl_Lr* t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LLr *dl_LLr_slice(const dl_LLr *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LLr_from(b - a + 1, l->items + a);
}

static dan_str dl_LLr_str(const dl_LLr *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dl_Lr_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LLr_find(const dl_LLr *l, dl_Lr* b) {
    for (int64_t i = 0; i < l->len; i++) { dl_Lr* a = l->items[i]; if (dl_Lr_eq(a, b)) return i; }
    return -1;
}
static bool dl_LLr_contains(const dl_LLr *l, dl_Lr* b) { return dl_LLr_find(l, b) >= 0; }
static bool dl_LLr_eq(const dl_LLr *x, const dl_LLr *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dl_Lr* a = x->items[i]; dl_Lr* b = y->items[i]; if (!(dl_Lr_eq(a, b))) return false; }
    return true;
}


