/* ---- fractions, rounding, roots, units ---- */

static dan_rat dan_rat_abs(dan_rat a, int line) { return a.n < 0 ? dan_rat_neg(a, line) : a; }

/* 7/3 -> "2 1/3", -7/3 -> "-2 1/3", 1/3 -> "1/3", 6/3 -> "2" */
static dan_str dan_mixed_str(dan_rat a) {
    char b[96];
    uint64_t un = a.n < 0 ? (uint64_t)0 - (uint64_t)a.n : (uint64_t)a.n;
    uint64_t whole = un / (uint64_t)a.d, rest = un % (uint64_t)a.d;
    const char *sign = a.n < 0 ? "-" : "";
    if (rest == 0) snprintf(b, sizeof b, "%s%llu", sign, (unsigned long long)whole);
    else if (whole == 0) snprintf(b, sizeof b, "%s%llu/%lld", sign, (unsigned long long)rest, (long long)a.d);
    else snprintf(b, sizeof b, "%s%llu %llu/%lld", sign, (unsigned long long)whole,
                  (unsigned long long)rest, (long long)a.d);
    return dan_strdup(b);
}

static dan_rat dan_mixed_make(int64_t whole, int64_t num, int64_t den, int line) {
    if (num < 0 || den <= 0) dan_error(DAN_MSG_MIXED, line);
    dan_rat part = dan_rat_of(num, den, line);
    dan_rat w = dan_rat_from_int(whole < 0 ? -whole : whole, line);
    dan_rat r = dan_rat_add(w, part, line);
    return whole < 0 ? dan_rat_neg(r, line) : r;
}

/* Decimal notation with the repeating part in brackets: 1/6 -> "0,1(6)" */
static dan_str dan_periodic(dan_rat a, int line) {
    uint64_t un = a.n < 0 ? (uint64_t)0 - (uint64_t)a.n : (uint64_t)a.n;
    uint64_t d = (uint64_t)a.d;
    char head[48];
    snprintf(head, sizeof head, "%s%llu", a.n < 0 ? "-" : "", (unsigned long long)(un / d));
    uint64_t r = un % d;
    if (r == 0) return dan_strdup(head);
    /* pre-period length: the larger power of 2 or 5 in the denominator */
    int c2 = 0, c5 = 0;
    uint64_t t = d;
    while (t % 2 == 0) { t /= 2; c2++; }
    while (t % 5 == 0) { t /= 5; c5++; }
    int pre = c2 > c5 ? c2 : c5;
    size_t cap = 64, len = 0;
    char *digits = dan_alloc(cap);
    for (int i = 0; i < pre; i++) {
        dan_u128 x = (dan_u128)r * 10;
        if (len + 2 >= cap) { cap *= 2; digits = dan_realloc(digits, cap); }
        digits[len++] = (char)('0' + (int)(x / d));
        r = (uint64_t)(x % d);
    }
    size_t period_start = len;
    if (r != 0) {
        uint64_t start = r;
        do {
            dan_u128 x = (dan_u128)r * 10;
            if (len + 4 >= cap) { cap *= 2; digits = dan_realloc(digits, cap); }
            digits[len++] = (char)('0' + (int)(x / d));
            r = (uint64_t)(x % d);
            if (len - period_start > 100000) dan_error(DAN_MSG_PERIOD_LONG, line);
        } while (r != start);
    }
    size_t hl = strlen(head);
    char *out = dan_str_new(hl + len + 3);
    memcpy(out, head, hl);
    out[hl] = ',';
    memcpy(out + hl + 1, digits, period_start);
    size_t pos = hl + 1 + period_start;
    if (len > period_start) {
        out[pos++] = '(';
        memcpy(out + pos, digits + period_start, len - period_start);
        pos += len - period_start;
        out[pos++] = ')';
    }
    out[pos] = 0;
    dan_free(digits);
    return out;
}

/* School rounding (half away from zero) on the shortest decimal form of the
   number, so that 2.675 rounds to 2.68 exactly as written. */
static double dan_round_decimal(double v, int64_t places) {
    if (v != v || v - v != 0 || places > 17) return v;
    char buf[64];
    for (int prec = 0; prec <= 16; prec++) {
        snprintf(buf, sizeof buf, "%.*e", prec, v);
        if (strtod(buf, NULL) == v) break;
    }
    const char *p = buf;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; }
    char digits[32];
    int nd = 0;
    for (; *p && *p != 'e'; p++) if (*p >= '0' && *p <= '9') digits[nd++] = *p;
    long e10 = strtol(p + 1, NULL, 10);
    long keep = e10 + 1 + (long)places;      /* digits kept before the cut */
    if (keep >= nd) return v;
    if (keep < 0) return neg ? -0.0 : 0.0;
    uint64_t kept = 0;
    for (long i = 0; i < keep; i++) kept = kept * 10 + (uint64_t)(digits[i] - '0');
    if (digits[keep] >= '5') kept++;
    char out[64];
    snprintf(out, sizeof out, "%s%llue%ld", neg ? "-" : "", (unsigned long long)kept, e10 + 1 - keep);
    return strtod(out, NULL);
}

static int64_t dan_round_float(double v, int line) {
    double r = dan_round_decimal(v, 0);
    return dan_float_to_int(r, line);
}

static int64_t dan_round_rat(dan_rat a, int line) {
    (void)line;
    dan_i128 n = a.n < 0 ? -(dan_i128)a.n : a.n;
    dan_i128 q = (2 * n + a.d) / (2 * (dan_i128)a.d);
    return (int64_t)(a.n < 0 ? -q : q);
}

static double dan_round_float_places(double v, int64_t places, int line) {
    (void)line;
    return dan_round_decimal(v, places);
}

static dan_i128 dan_pow10_128(int64_t k) { dan_i128 r = 1; while (k-- > 0) r *= 10; return r; }

static double dan_round_rat_places(dan_rat a, int64_t places, int line) {
    if (places > 18 || places < -18) return dan_round_decimal(dan_rat_to_float(a), places);
    dan_i128 n = a.n < 0 ? -(dan_i128)a.n : a.n, d = a.d;
    if (places >= 0) n *= dan_pow10_128(places); else d *= dan_pow10_128(-places);
    dan_i128 q = (2 * n + d) / (2 * d);
    double r = places >= 0 ? (double)q / (double)dan_pow10_128(places) : (double)q * (double)dan_pow10_128(-places);
    (void)line;
    r = dan_round_decimal(r, places);
    return a.n < 0 ? -r : r;
}

/* Rounding an integer to tens, hundreds, ...: (1234, -2) -> 1200 */
static int64_t dan_round_int_places(int64_t v, int64_t places, int line) {
    if (places >= 0) return v;
    if (places < -18) return 0;
    dan_i128 p = dan_pow10_128(-places);
    dan_i128 n = v < 0 ? -(dan_i128)v : v;
    dan_i128 q = (2 * n + p) / (2 * p) * p;
    if (q > INT64_MAX) dan_error(DAN_MSG_TOO_BIG, line);
    return (int64_t)(v < 0 ? -q : q);
}

static double dan_sqrt(double v, int line) {
    if (v < 0) dan_error(DAN_MSG_SQRT_NEG, line);
    return sqrt(v);
}

static int64_t dan_isqrt(int64_t n, int line) {
    if (n < 0) dan_error(DAN_MSG_SQRT_NEG, line);
    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > (uint64_t)n) r--;
    while ((r + 1) * (r + 1) <= (uint64_t)n) r++;
    return (int64_t)r;
}

static const dan_unit *dan_find_unit(dan_str name, int line) {
    for (size_t i = 0; i < sizeof dan_units / sizeof dan_units[0]; i++)
        if (strcmp(dan_units[i].name, name) == 0) return &dan_units[i];
    dan_conv_error(DAN_MSG_UNIT_UNKNOWN, name, line);
    return NULL;
}

static double dan_convert_units(double v, dan_str from, dan_str to, int line) {
    const dan_unit *a = dan_find_unit(from, line), *b = dan_find_unit(to, line);
    if (a->kind != b->kind) {
        char buf[300];
        snprintf(buf, sizeof buf, DAN_MSG_UNIT_KIND, from, to);
        dan_error(buf, line);
    }
    double r = v * (a->num * b->den) / (a->den * b->num);
    char t[64];
    snprintf(t, sizeof t, "%.15g", r);          /* remove binary noise: 0.30000000000000004 */
    return strtod(t, NULL);
}


static int dan_cmp_i(int64_t x, int64_t y) { return (x > y) - (x < y); }
static int dan_qcmp_i(const void *a, const void *b) { return dan_cmp_i(*(const int64_t *)a, *(const int64_t *)b); }
static dl_Li *dan_sorted_i(const dl_Li *l) {
    dl_Li *r = dl_Li_from(l->len, l->items);
    qsort(r->items, (size_t)r->len, sizeof(int64_t), dan_qcmp_i);
    return r;
}

static dl_Li *dan_set_i(const dl_Li *l) {
    dl_Li *s = dan_sorted_i(l);
    int64_t k = 0;
    for (int64_t i = 0; i < s->len; i++)
        if (k == 0 || dan_cmp_i(s->items[k - 1], s->items[i]) != 0) s->items[k++] = s->items[i];
        else DAN_NOREL(s->items[i]);
    s->len = k;
    return s;
}
static bool dan_contains_i(int64_t x, const dl_Li *l) {
    for (int64_t i = 0; i < l->len; i++) if (dan_cmp_i(l->items[i], x) == 0) return true;
    return false;
}
static dl_Li *dan_union_i(const dl_Li *a, const dl_Li *b) {
    dl_Li *r = dl_Li_from(a->len, a->items);
    for (int64_t i = 0; i < b->len; i++) dl_Li_push(r, b->items[i]);
    return dan_set_i(r);
}
static dl_Li *dan_intersection_i(const dl_Li *a, const dl_Li *b) {
    dl_Li *r = dl_Li_from(0, NULL);
    for (int64_t i = 0; i < a->len; i++) if (dan_contains_i(a->items[i], b)) dl_Li_push(r, a->items[i]);
    return dan_set_i(r);
}
static dl_Li *dan_difference_i(const dl_Li *a, const dl_Li *b) {
    dl_Li *r = dl_Li_from(0, NULL);
    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_i(a->items[i], b)) dl_Li_push(r, a->items[i]);
    return dan_set_i(r);
}
static bool dan_subset_i(const dl_Li *a, const dl_Li *b) {
    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_i(a->items[i], b)) return false;
    return true;
}

static void dan_need_items_i(const dl_Li *l, int line) { if (l->len == 0) dan_error(DAN_MSG_EMPTY_STAT, line); }
static int64_t dan_sum_i(const dl_Li *l, int line) {
    (void)line;
    int64_t s = 0;
    for (int64_t i = 0; i < l->len; i++) s = s + l->items[i];
    return s;
}
static double dan_mean_i(const dl_Li *l, int line) { dan_need_items_i(l, line); return (double)dan_sum_i(l, line) / (double)l->len; }
static double dan_median_i(const dl_Li *l, int line) {
    dan_need_items_i(l, line);
    dl_Li *s = dan_sorted_i(l);
    int64_t m = s->len / 2;
    if (s->len % 2 == 0) return ((double)s->items[m - 1] + (double)s->items[m]) / 2.0;
    return (double)s->items[m];
}
static int64_t dan_min_i(const dl_Li *l, int line) {
    dan_need_items_i(l, line);
    int64_t r = l->items[0];
    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_i(l->items[i], r) < 0) r = l->items[i];
    return r;
}
static int64_t dan_max_i(const dl_Li *l, int line) {
    dan_need_items_i(l, line);
    int64_t r = l->items[0];
    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_i(l->items[i], r) > 0) r = l->items[i];
    return r;
}
static int64_t dan_min2_i(int64_t x, int64_t y) { return dan_cmp_i(x, y) <= 0 ? x : y; }
static int64_t dan_max2_i(int64_t x, int64_t y) { return dan_cmp_i(x, y) >= 0 ? x : y; }
static int64_t dan_range_i(const dl_Li *l, int line) {
    int64_t a = dan_min_i(l, line), b = dan_max_i(l, line);
    return b - a;
}

static int dan_cmp_r(dan_rat x, dan_rat y) { return dan_rat_cmp(x, y); }
static int dan_qcmp_r(const void *a, const void *b) { return dan_cmp_r(*(const dan_rat *)a, *(const dan_rat *)b); }
static dl_Lr *dan_sorted_r(const dl_Lr *l) {
    dl_Lr *r = dl_Lr_from(l->len, l->items);
    qsort(r->items, (size_t)r->len, sizeof(dan_rat), dan_qcmp_r);
    return r;
}

static void dan_need_items_r(const dl_Lr *l, int line) { if (l->len == 0) dan_error(DAN_MSG_EMPTY_STAT, line); }
static dan_rat dan_sum_r(const dl_Lr *l, int line) {
    (void)line;
    dan_rat s = dan_rat_from_int(0, line);
    for (int64_t i = 0; i < l->len; i++) s = dan_rat_add(s, l->items[i], line);
    return s;
}
static dan_rat dan_mean_r(const dl_Lr *l, int line) { dan_need_items_r(l, line); return dan_rat_div(dan_sum_r(l, line), dan_rat_from_int(l->len, line), line); }
static dan_rat dan_median_r(const dl_Lr *l, int line) {
    dan_need_items_r(l, line);
    dl_Lr *s = dan_sorted_r(l);
    int64_t m = s->len / 2;
    if (s->len % 2 == 0) return dan_rat_div(dan_rat_add(s->items[m - 1], s->items[m], line), dan_rat_from_int(2, line), line);
    return s->items[m];
}
static dan_rat dan_min_r(const dl_Lr *l, int line) {
    dan_need_items_r(l, line);
    dan_rat r = l->items[0];
    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_r(l->items[i], r) < 0) r = l->items[i];
    return r;
}
static dan_rat dan_max_r(const dl_Lr *l, int line) {
    dan_need_items_r(l, line);
    dan_rat r = l->items[0];
    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_r(l->items[i], r) > 0) r = l->items[i];
    return r;
}
static dan_rat dan_min2_r(dan_rat x, dan_rat y) { return dan_cmp_r(x, y) <= 0 ? x : y; }
static dan_rat dan_max2_r(dan_rat x, dan_rat y) { return dan_cmp_r(x, y) >= 0 ? x : y; }
static dan_rat dan_range_r(const dl_Lr *l, int line) {
    dan_rat a = dan_min_r(l, line), b = dan_max_r(l, line);
    return dan_rat_sub(b, a, line);
}

